/**
 * MosaicDocumentCriteriaPanel — the review panel for one row.
 *
 * Built on MosaicTabs + MosaicResizableSplitPane + MosaicPdfViewer +
 * MosaicEditableCell. It OPENS ON COMPARE (document left, fields right) with no
 * interaction; the other tabs show the document alone or the fields alone. Every
 * field is editable (unless its column says otherwise) and shows a provenance
 * label supplied by the host. Editing reports a correction request carrying the
 * actor and the correction provenance. Prev/next walk the host's row order.
 *
 * No business vocabulary and no default copy: every word is in `labels` or in
 * the column model.
 */
import { useState } from "react";
import { MosaicEditableCell } from "@/components/ui/MosaicEditableCell";
import { MosaicPdfViewer } from "@/components/ui/MosaicPdfViewer";
import { MosaicResizableSplitPane } from "@/components/ui/MosaicResizableSplitPane";
import {
  MosaicTabs,
  MosaicTabsList,
  MosaicTabsPanel,
  MosaicTabsTrigger,
} from "@/components/ui/MosaicTabs";
import {
  type ColumnVisibility,
  type FieldCorrectionRequest,
  INITIAL_REVIEW_PANEL_TAB,
  REVIEW_PANEL_TABS,
  type ReviewColumn,
  type ReviewPanelTab,
  initialColumnVisibility,
  neighbourRowId,
  visibleColumns,
} from "./document-review-logic.js";

export interface MosaicDocumentCriteriaPanelLabels {
  tabCompare: string;
  tabDocument: string;
  tabRow: string;
  previous: string;
  next: string;
  documentLoading: string;
  documentError: string;
  collapse: string;
  resize: string;
  /** Accessible name of a field's editor, from its column label. */
  editField: (columnLabel: string) => string;
}

export interface MosaicDocumentCriteriaPanelProps<T> {
  row: T;
  rowId: string;
  /** The column model; the fields shown are its visible columns. */
  columns: ReviewColumn<T>[];
  /** Overrides the model's `defaultVisible` per column id. */
  columnVisibility?: ColumnVisibility;
  documentUrl: string;
  /** Row ids in display order. */
  orderedRowIds: readonly string[];
  onNavigate: (rowId: string) => void;
  /** Receives the correction request, with actor and provenance. */
  onCorrect: (request: FieldCorrectionRequest) => unknown;
  /** Who is correcting. */
  actor: string;
  /** Provenance tag recorded with every correction made from this panel. */
  correctionProvenance: string;
  /** Provenance label shown next to a field (source name, corrected by…), or null for none. */
  provenanceLabel: (row: T, column: ReviewColumn<T>) => string | null;
  labels: MosaicDocumentCriteriaPanelLabels;
  /** Defaults to Compare. */
  defaultTab?: ReviewPanelTab;
  className?: string;
}

export function MosaicDocumentCriteriaPanel<T>({
  row,
  rowId,
  columns,
  columnVisibility,
  documentUrl,
  orderedRowIds,
  onNavigate,
  onCorrect,
  actor,
  correctionProvenance,
  provenanceLabel,
  labels,
  defaultTab = INITIAL_REVIEW_PANEL_TAB,
  className,
}: MosaicDocumentCriteriaPanelProps<T>) {
  const [tab, setTab] = useState<ReviewPanelTab>(defaultTab);
  const [sideWidth, setSideWidth] = useState(45);
  const [isSideCollapsed, setIsSideCollapsed] = useState(false);

  const previousId = neighbourRowId(orderedRowIds, rowId, "prev");
  const nextId = neighbourRowId(orderedRowIds, rowId, "next");

  const tabLabel: Record<ReviewPanelTab, string> = {
    compare: labels.tabCompare,
    document: labels.tabDocument,
    row: labels.tabRow,
  };

  const document_ = (
    <MosaicPdfViewer
      fileUrl={documentUrl}
      loadingLabel={labels.documentLoading}
      errorLabel={labels.documentError}
    />
  );

  const fields = (
    <dl data-slot="document-criteria-fields" className="flex flex-col gap-3 p-3">
      {visibleColumns(columns, columnVisibility ?? initialColumnVisibility(columns)).map(
        (column) => {
          const value = column.accessor(row);
          const provenance = provenanceLabel(row, column);
          return (
            <div
              key={column.id}
              data-slot="document-criteria-field"
              className="flex flex-col gap-1"
            >
              <dt className="text-xs font-medium text-muted-foreground">{column.label}</dt>
              <dd className="m-0 flex flex-col gap-1">
                <MosaicEditableCell
                  value={value === null ? "" : String(value)}
                  disabled={column.editable === false}
                  editAriaLabel={labels.editField(column.label)}
                  onCommit={(input) => {
                    onCorrect({
                      rowId,
                      field: column.id,
                      input,
                      by: actor,
                      provenance: correctionProvenance,
                    });
                  }}
                />
                {provenance ? (
                  <span
                    data-slot="document-criteria-provenance"
                    className="text-xs text-muted-foreground"
                  >
                    {provenance}
                  </span>
                ) : null}
              </dd>
            </div>
          );
        },
      )}
    </dl>
  );

  return (
    <section
      data-slot="document-criteria-panel"
      data-row-id={rowId}
      className={["flex flex-col gap-2 rounded-md border border-border p-2", className]
        .filter(Boolean)
        .join(" ")}
    >
      <MosaicTabs value={tab} onValueChange={(next) => setTab(next as ReviewPanelTab)}>
        <div className="flex items-center justify-between gap-2">
          <MosaicTabsList>
            {REVIEW_PANEL_TABS.map((value) => (
              <MosaicTabsTrigger key={value} value={value}>
                {tabLabel[value]}
              </MosaicTabsTrigger>
            ))}
          </MosaicTabsList>
          <div className="flex gap-2">
            <button
              type="button"
              disabled={previousId === null}
              onClick={() => previousId !== null && onNavigate(previousId)}
              className="rounded-md border border-border px-3 py-1 text-sm disabled:opacity-50"
            >
              {labels.previous}
            </button>
            <button
              type="button"
              disabled={nextId === null}
              onClick={() => nextId !== null && onNavigate(nextId)}
              className="rounded-md border border-border px-3 py-1 text-sm disabled:opacity-50"
            >
              {labels.next}
            </button>
          </div>
        </div>
        <MosaicTabsPanel value="compare">
          <MosaicResizableSplitPane
            main={document_}
            side={fields}
            sideWidth={sideWidth}
            onSideWidthChange={setSideWidth}
            isSideCollapsed={isSideCollapsed}
            onToggleSideCollapsed={() => setIsSideCollapsed((c) => !c)}
            collapseButtonAriaLabel={labels.collapse}
            resizeHandleAriaLabel={labels.resize}
          />
        </MosaicTabsPanel>
        <MosaicTabsPanel value="document">{document_}</MosaicTabsPanel>
        <MosaicTabsPanel value="row">{fields}</MosaicTabsPanel>
      </MosaicTabs>
    </section>
  );
}

MosaicDocumentCriteriaPanel.displayName = "MosaicDocumentCriteriaPanel";

/**
 * MosaicDocumentTable — generic document table, a composition of GrilleRegistre.
 *
 * One table component serves every document screen: this module renders through
 * the library's shared AG Grid (GrilleRegistre) and adds only the document-review
 * contract on top of it — the column model, the row selection and the panel.
 *
 * Rows and the column model come from props; column visibility comes from the
 * model (`defaultVisible`) unless the host passes a `columnVisibility` override.
 * Selecting a row (click, Enter, Space) opens `renderPanel` for that row. The
 * module ships no business vocabulary: every label is a prop, the empty state
 * included (GrilleRegistre's `messageVide`).
 *
 * Row activation: the first visible column renders its value inside a real
 * `<button>` (keyboard + assistive tech), and a click on any cell of a row —
 * the button's keyboard activation arrives as a click — is resolved to its row
 * through the grid's `onCellClicked`, one path for both. Grid cells take no focus
 * of their own (`suppressCellFocus`), so each row's button is its keyboard stop.
 *
 * Sorting and filtering are off on every column: the table keeps the host's row
 * order, which is also the order prev/next navigation walks (`orderedRowIds`).
 */
import type { CellClickedEvent, ColDef, ICellRendererParams } from "ag-grid-community";
import { createContext, useContext, useMemo, useState } from "react";
import type * as React from "react";
import { GrilleRegistre } from "@/components/ui/GrilleRegistre";
import { refitColumns } from "@/components/ui/grid-theme";
import {
  type ColumnVisibility,
  type ReviewColumn,
  initialColumnVisibility,
  visibleColumns,
} from "./document-review-logic.js";

export interface MosaicDocumentTableRowContext {
  rowId: string;
  /** Row ids in display order — what prev/next navigation walks. */
  orderedRowIds: string[];
  /** Select another row (the panel stays open on it). */
  selectRow: (rowId: string) => void;
  /** Close the panel. */
  closeRow: () => void;
}

export interface MosaicDocumentTableProps<T> {
  columns: ReviewColumn<T>[];
  rows: T[];
  getRowId: (row: T) => string;
  /** Overrides the model's `defaultVisible` per column id. */
  columnVisibility?: ColumnVisibility;
  /** Controlled selection. Omit for internal state. */
  selectedRowId?: string | null;
  onSelectedRowChange?: (rowId: string | null) => void;
  /** Rendered for the selected row. */
  renderPanel?: (row: T, context: MosaicDocumentTableRowContext) => React.ReactNode;
  /** Required — the host owns the language. */
  emptyMessage: string;
  className?: string;
}

// The selected row id reaches the first-column renderer through React context:
// ag-grid-react renders cell renderers in portals of this tree, so a selection
// change re-renders the marked button without rebuilding the column definitions.
const SelectedRowIdContext = createContext<string | null>(null);

function OpenRowButton({ value, node }: ICellRendererParams) {
  const selectedRowId = useContext(SelectedRowIdContext);
  const isSelected = node.id !== undefined && node.id === selectedRowId;
  return (
    <button
      type="button"
      data-slot="document-table-open"
      aria-current={isSelected ? "true" : undefined}
      data-selected={isSelected ? "true" : undefined}
      className="text-left underline-offset-2 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      {value as string}
    </button>
  );
}

export function MosaicDocumentTable<T>({
  columns,
  rows,
  getRowId,
  columnVisibility,
  selectedRowId: controlledSelectedRowId,
  onSelectedRowChange,
  renderPanel,
  emptyMessage,
  className,
}: MosaicDocumentTableProps<T>) {
  const [internalSelectedRowId, setInternalSelectedRowId] = useState<string | null>(null);
  const isControlled = controlledSelectedRowId !== undefined;
  const selectedRowId = isControlled ? controlledSelectedRowId : internalSelectedRowId;

  function select(rowId: string | null) {
    if (!isControlled) setInternalSelectedRowId(rowId);
    onSelectedRowChange?.(rowId);
  }

  const columnDefs = useMemo<ColDef<T>[]>(
    () =>
      visibleColumns(columns, columnVisibility ?? initialColumnVisibility(columns)).map(
        (column, columnIndex) => ({
          colId: column.id,
          headerName: column.label,
          // The column model's value, as text: null reads as an empty cell.
          valueGetter: (params) => {
            if (params.data === undefined) return "";
            const value = column.accessor(params.data);
            return value === null ? "" : String(value);
          },
          // No type inference: a boolean stays text, never a grid checkbox.
          cellDataType: false,
          sortable: false,
          filter: false,
          floatingFilter: false,
          ...(columnIndex === 0 ? { cellRenderer: OpenRowButton } : {}),
        }),
      ),
    [columns, columnVisibility],
  );

  function handleCellClicked(event: CellClickedEvent<T>) {
    if (event.data !== undefined) select(getRowId(event.data));
  }

  const orderedRowIds = rows.map(getRowId);
  const selectedRow =
    selectedRowId === null ? undefined : rows.find((row) => getRowId(row) === selectedRowId);

  return (
    <div data-slot="document-table" className={className}>
      <SelectedRowIdContext.Provider value={selectedRowId}>
        <GrilleRegistre<T>
          lignes={rows}
          columnDefs={columnDefs}
          getRowId={getRowId}
          onCellClicked={handleCellClicked}
          suppressCellFocus
          domLayout="autoHeight"
          onGridSizeChanged={refitColumns}
          messageVide={emptyMessage}
        />
      </SelectedRowIdContext.Provider>
      {selectedRow !== undefined && renderPanel
        ? renderPanel(selectedRow, {
            rowId: getRowId(selectedRow),
            orderedRowIds,
            selectRow: (rowId) => select(rowId),
            closeRow: () => select(null),
          })
        : null}
    </div>
  );
}

MosaicDocumentTable.displayName = "MosaicDocumentTable";

/**
 * Generic column model. Ships no field name and no label of its own: ids, labels
 * and accessors all come from the host.
 */

export type FieldValue = string | number | boolean | null;

export interface ReviewColumn<T> {
  /** Stable column id. */
  id: string;
  /** Host-supplied label (the host owns the language). */
  label: string;
  /** Whether the column is shown before the user changes anything. */
  defaultVisible: boolean;
  /** Reads this column's value from a row. */
  accessor: (row: T) => FieldValue;
  /** False for derived columns that must never be typed by hand. Defaults to true. */
  editable?: boolean;
}

/** Explicit visibility per column id; an absent id falls back to `defaultVisible`. */
export type ColumnVisibility = Readonly<Record<string, boolean>>;

// Developer-facing invariant error, thrown at misuse time, never rendered to an end
// user. Kept as an object-literal constant with the marker BETWEEN properties: a `//`
// comment right before a `throw new Error(...)` is stripped by esbuild and would never
// reach dist (same pattern as MosaicDeviceProvider).
const COLUMN_MODEL_ERRORS = {
  // allow-hardcoded-word: developer-facing invariant error, never rendered to an end user
  unknownColumn: (id: string) => `document-review: visibility names unknown column "${id}"`,
};

function assertKnown<T>(columns: readonly ReviewColumn<T>[], ids: Iterable<string>): void {
  const known = new Set(columns.map((c) => c.id));
  for (const id of ids) {
    if (!known.has(id)) {
      throw new Error(COLUMN_MODEL_ERRORS.unknownColumn(id));
    }
  }
}

export function initialColumnVisibility<T>(columns: readonly ReviewColumn<T>[]): ColumnVisibility {
  return Object.fromEntries(columns.map((c) => [c.id, c.defaultVisible]));
}

export function toggleColumnVisibility<T>(
  columns: readonly ReviewColumn<T>[],
  visibility: ColumnVisibility,
  id: string,
): ColumnVisibility {
  assertKnown(columns, [id]);
  const column = columns.find((c) => c.id === id) as ReviewColumn<T>;
  const current = visibility[id] ?? column.defaultVisible;
  return { ...visibility, [id]: !current };
}

/** Columns to show, in column order. An unknown id in `visibility` throws, naming it. */
export function visibleColumns<T>(
  columns: readonly ReviewColumn<T>[],
  visibility: ColumnVisibility,
): ReviewColumn<T>[] {
  assertKnown(columns, Object.keys(visibility));
  return columns.filter((c) => visibility[c.id] ?? c.defaultVisible);
}

export { INITIAL_REVIEW_PANEL_TAB, REVIEW_PANEL_TABS } from "./panel-tab.js";
export type { ReviewPanelTab } from "./panel-tab.js";
export { isEditableTarget, neighbourRowId } from "./row-navigation.js";
export type { NavDirection } from "./row-navigation.js";
export {
  initialColumnVisibility,
  toggleColumnVisibility,
  visibleColumns,
} from "./column-model.js";
export type { ColumnVisibility, FieldValue, ReviewColumn } from "./column-model.js";
export { applyFieldCorrection, correctionOutcome } from "./field-correction.js";
export type {
  ApplyFieldCorrectionArgs,
  CorrectionRecord,
  FieldCorrectionRequest,
  FieldCorrectionResult,
  FieldValidation,
  FieldValidator,
  FieldWriteResponse,
  ReviewRow,
} from "./field-correction.js";

/**
 * The write path of a field correction: validate, write, and on failure hand back
 * the row from BEFORE.
 *
 * A failed write must never leave the screen showing a value the store does not
 * hold. The function is pure with respect to its input: it never mutates the row,
 * it returns a new one, so the caller replaces what it displays with what comes
 * back and has no decision to take.
 *
 * Provenance: the ORIGINAL value is kept (the first one, across successive
 * corrections), next to the corrected value, who made it, when, and the host's
 * provenance tag.
 */
import type { FieldValue } from "./column-model.js";

export interface CorrectionRecord {
  original: FieldValue;
  corrected: FieldValue;
  by: string;
  /** ISO-8601 instant. */
  at: string;
  provenance: string;
}

export interface ReviewRow {
  id: string;
  values: Readonly<Record<string, FieldValue>>;
  corrections?: Readonly<Record<string, CorrectionRecord>>;
}

/** What the correction UI hands to the host, and what the host passes on to the writer. */
export interface FieldCorrectionRequest {
  rowId: string;
  field: string;
  /** The user's raw input. */
  input: string;
  by: string;
  provenance: string;
}

/**
 * `value` is the value as the store re-read it. It is OPTIONAL on purpose: a store
 * that does not echo it yields an unconfirmed result, never a silent success.
 * Presence is what counts (`"value" in response`): `null` confirms an erasure.
 */
export type FieldWriteResponse = { ok: true; value?: FieldValue } | { ok: false; message: string };

export type FieldValidation = { ok: true; value: FieldValue } | { ok: false; message: string };

export type FieldValidator = (field: string, input: string, row: ReviewRow) => FieldValidation;

export interface ApplyFieldCorrectionArgs extends Omit<FieldCorrectionRequest, "rowId"> {
  row: ReviewRow;
  write: (request: FieldCorrectionRequest) => Promise<FieldWriteResponse>;
  /** Defaults to accepting the raw input as the value. */
  validate?: FieldValidator;
  /** Injectable clock, ISO-8601. Defaults to the current instant. */
  now?: () => string;
}

export type FieldCorrectionResult =
  | { ok: true; row: ReviewRow; confirmed: boolean }
  | { ok: false; row: ReviewRow; message: string };

export async function applyFieldCorrection(
  args: ApplyFieldCorrectionArgs,
): Promise<FieldCorrectionResult> {
  const { row, field, input, by, provenance, write, validate, now } = args;

  const checked: FieldValidation = validate
    ? validate(field, input, row)
    : { ok: true, value: input };
  if (!checked.ok) return { ok: false, row, message: checked.message };

  let response: FieldWriteResponse;
  try {
    response = await write({ rowId: row.id, field, input, by, provenance });
  } catch (e) {
    // The thrown message is kept verbatim: rewording it would remove what lets the user fix it.
    return { ok: false, row, message: e instanceof Error ? e.message : String(e) };
  }
  if (!response.ok) return { ok: false, row, message: response.message };

  const confirmed = "value" in response;
  // Unconfirmed: show what was sent, and say so through `confirmed: false`.
  const corrected: FieldValue = confirmed ? (response.value ?? null) : checked.value;
  const original = row.corrections?.[field]?.original ?? row.values[field] ?? null;
  const record: CorrectionRecord = {
    original,
    corrected,
    by,
    at: now ? now() : new Date().toISOString(),
    provenance,
  };
  return {
    ok: true,
    confirmed,
    row: {
      ...row,
      values: { ...row.values, [field]: corrected },
      corrections: { ...row.corrections, [field]: record },
    },
  };
}

/** Three outcomes, never two: "uncertain" is a write that succeeded but was not read back. */
export function correctionOutcome(result: FieldCorrectionResult): "ok" | "uncertain" | "failed" {
  if (!result.ok) return "failed";
  return result.confirmed ? "ok" : "uncertain";
}

/**
 * The tabs of a document-review panel, named by ROLE (never by a business noun).
 *
 * - "compare"  document and fields side by side — the INITIAL tab.
 * - "document" the document alone.
 * - "row"      the row's fields alone.
 */
export type ReviewPanelTab = "compare" | "document" | "row";

export const REVIEW_PANEL_TABS: readonly ReviewPanelTab[] = ["compare", "document", "row"];

/** A panel opens on Compare: reading the document and editing the fields at once is the point. */
export const INITIAL_REVIEW_PANEL_TAB: ReviewPanelTab = "compare";

// The caller passes the table's current display order; this module never derives its own.

export type NavDirection = "prev" | "next";

// Arrow keys inside a field move the caret or the option, never the row.
export function isEditableTarget(target: EventTarget | null): boolean {
  return (
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement ||
    (target instanceof HTMLElement && target.isContentEditable === true)
  );
}

/** Neighbour row id, or null at either end or when the current id is not listed. */
export function neighbourRowId(
  orderedRowIds: readonly string[],
  currentRowId: string,
  direction: NavDirection,
): string | null {
  const index = orderedRowIds.indexOf(currentRowId);
  if (index === -1) return null;
  const neighbourIndex = index + (direction === "next" ? 1 : -1);
  if (neighbourIndex < 0 || neighbourIndex >= orderedRowIds.length) return null;
  return orderedRowIds[neighbourIndex] ?? null;
}
